mapper.select:



        and io.inbound_status = #{params.inboundStatus}


        and io.inbound_type = #{params.inboundType}


        and io.inbound_order_id like concat('%', #{params.inboundOrderId}, '%')


        and io.inbound_batch_id like concat('%', #{params.inboundBatchId}, '%')


        and io.warehouse_id = #{params.warehouseId}


        and io.supplier_id = #{params.supplierId}


        and date(io.created_at) >= #{params.startDate}


        and date(io.created_at) <= #{params.endDate}


        and (io.inbound_order_id like concat('%', #{params.keyword}, '%')
             or io.related_order_no like concat('%', #{params.keyword}, '%')
             or w.warehouse_name like concat('%', #{params.keyword}, '%'))


order by io.created_at desc

select count(1)
from inbound_order io


        and io.inbound_status = #{params.inboundStatus}


        and io.inbound_type = #{params.inboundType}


        and io.warehouse_id = #{params.warehouseId}

select inbound_status as status, count(1) as count from inbound_order
warehouse_id = #{warehouseId}
group by inbound_status

select inbound_type as type, CASE inbound_type WHEN 0 THEN '生产入库' WHEN 1 THEN '采购入库' WHEN 2 THEN '调拨入库' ELSE '' END as type_name, count(1) as count, sum(total_quantity) as total_quantity from inbound_order
and date(created_at) >= #{startDate}
and date(created_at) <= #{endDate}
group by inbound_type
